<script setup lang="ts">
import { ref } from 'vue'
import AppIcon from './AppIcon.vue'
defineProps<{ username: string; password: string; busy: boolean; error: string; status: string; detail: string; healthy: boolean; checking: boolean; unavailable: boolean }>()
const emit = defineEmits<{ 'update:username': [value: string]; 'update:password': [value: string]; login: []; join: [code: string]; check: [] }>()
const mode = ref<'director' | 'participant'>('director')
const reveal = ref(false), code = ref('')
function submit() { if (mode.value === 'participant' || code.value.trim()) emit('join', code.value.trim()); else emit('login') }
</script>
<template>
  <main id="main-content" class="atlas-login">
    <section class="atlas-login__scene" aria-label="社区消防演练">
      <img class="atlas-login__image" src="/assets/atlas-community-night.png" alt="夜间社区消防演练场景效果图" fetchpriority="high" />
      <div class="atlas-login__brand"><AppIcon name="building" :size="76" /><div><strong>智演安巷</strong><span>面向老旧小区消防治理的数字孪生与智能决策平台</span></div></div>
      <button class="atlas-health" type="button" :disabled="checking" @click="emit('check')" :title="detail"><i :data-healthy="healthy"></i><span>{{ healthy ? '系统正常' : status }}<small>{{ checking ? '连接服务中' : '点击重新检查' }}</small></span></button>
      <div class="atlas-login__features"><div><AppIcon name="rescue" :size="30" /><p><strong>贴近真实场景的应急演练</strong><span>还原老旧小区典型风险，提升协同处置能力</span></p></div><div><AppIcon name="users" :size="30" /><p><strong>两端联动的全流程推演</strong><span>从发现、上报到处置、复盘，每一步都有依据</span></p></div></div>
      <footer>社区更安全 <span>居民更安心</span> 城市更有温度</footer>
    </section>
    <section class="atlas-login__auth" aria-labelledby="login-title">
      <header><h1 id="login-title">身份验证</h1><p>同心协力 · 防患未然 · 共建平安社区</p></header>
      <div class="atlas-login__roles" role="group" aria-label="选择使用端"><button :aria-pressed="mode === 'director'" @click="mode = 'director'"><AppIcon name="inspect" :size="32" /><span><strong>总控导演</strong><small>组织演练 · 全局指挥</small></span></button><button :aria-pressed="mode === 'participant'" @click="mode = 'participant'"><AppIcon name="users" :size="32" /><span><strong>参演处置</strong><small>接收任务 · 参与处置</small></span></button></div>
      <form class="atlas-login__form" @submit.prevent="submit">
        <template v-if="mode === 'director'">
          <label for="username">账号</label><div class="atlas-input"><AppIcon name="person" /><input id="username" :value="username" @input="emit('update:username', ($event.target as HTMLInputElement).value)" autocomplete="username" placeholder="请输入账号" :disabled="busy" :required="!code" maxlength="64" /></div>
          <label for="password">密码</label><div class="atlas-input"><AppIcon name="lock" /><input id="password" :value="password" @input="emit('update:password', ($event.target as HTMLInputElement).value)" :type="reveal ? 'text' : 'password'" autocomplete="current-password" placeholder="请输入密码" :disabled="busy" :required="!code" maxlength="128" /><button type="button" :aria-label="reveal ? '隐藏密码' : '显示密码'" @click="reveal = !reveal"><AppIcon :name="reveal ? 'eyeOff' : 'eye'" /></button></div>
          <div class="atlas-login__or"><span>或</span></div>
        </template>
        <label for="join-code">演练加入码</label><div class="atlas-input"><AppIcon name="phone" /><input id="join-code" v-model="code" placeholder="粘贴完整加入码…" maxlength="40" autocomplete="off" spellcheck="false" :required="mode === 'participant'" :disabled="busy" /></div><small>粘贴 32 位加入码，或直接打开导演分享的参演链接。</small>
        <p v-if="error" class="atlas-error" role="alert">{{ error }}</p>
        <button class="atlas-login__submit" type="submit" :disabled="busy || unavailable"><span>{{ busy ? '正在连接…' : mode === 'participant' || code ? '加入演练' : '进入工作台' }}</span><AppIcon name="arrowRight" /></button>
      </form>
      <footer><AppIcon name="lock" :size="17" />本地部署 · 离线可用</footer>
    </section>
  </main>
</template>
